 import { MeshPhysicalNodeMaterial, MeshBasicNodeMaterial } from 'three/webgpu';
import {
  uv as uvNode,
  texture as textureNode,
  uniform,
  mix,
  smoothstep,
  color as colorNode,
} from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const { THREE } = ctx;
  const { Group, Mesh, PlaneGeometry, PointLight, Vector3, Mesh: THREE.Mesh } = THREE;

  const root = new Group();
  const content = new Group();
  root.add(content);

  const specColors = config.intent?.visualSpec?.colors ?? config.colors ?? {};
  const ink = specColors.ink ?? '#16161d';
  const paper = specColors.paper ?? '#e8ecf2';
  const accent = specColors.accent ?? '#ff2a38';
  const surface = specColors.surface ?? '#0b0b10';

  // --- stage/backdrop ---
  const stageGeo = new PlaneGeometry(3.2, 0.95);
  const stageMat = new MeshBasicNodeMaterial({
    colorNode: mix(colorNode(surface), colorNode(ink), smoothstep(0.0, 1.0, uvNode().y)),
  });
  const stage = new THREE.Mesh(stageGeo, stageMat);
  stage.position.z = -0.08;
  content.add(stage);

  // --- row image with displacement depth map ---
  const segs = ctx.tier === 'T0' ? 32 : 64;
  const rowGeo = new PlaneGeometry(2.4, 0.68, segs, segs);
  const rowMat = new MeshPhysicalNodeMaterial({
    color: 0xffffff,
    metalness: 0.35,
    roughness: 0.55,
    clearcoat: 0.12,
    clearcoatRoughness: 0.4,
    side: THREE.FrontSide,
  });

  const row = new THREE.Mesh(rowGeo, rowMat);
  row.position.set(-0.28, 0, 0.01);
  content.add(row);

  // --- accent divider line ---
  const divGeo = new PlaneGeometry(0.04, 0.58);
  const divMat = new MeshBasicNodeMaterial({ color: new THREE.Color(accent) });
  const divider = new THREE.Mesh(divGeo, divMat);
  divider.position.set(1.08, 0, 0.04);
  content.add(divider);

  // --- rim accent light (helps metal read on dark stage) ---
  const rim = new PointLight(accent, 0.85, 6);
  rim.position.set(-1.2, 0.35, 1.2);
  content.add(rim);

  // --- load assets ---
  if (config.imageUrl) {
    ctx.textureLoader.loadTexture(config.imageUrl).then((tex) => {
      tex.colorSpace = THREE.SRGBColorSpace;
      rowMat.map = tex;
      rowMat.needsUpdate = true;
    });
  }
  if (config.depthMapUrl) {
    ctx.textureLoader.loadTexture(config.depthMapUrl).then((depthTex) => {
      depthTex.colorSpace = THREE.NoColorSpace;
      const displacementScale = uniform(0.08);
      rowMat.displacementNode = textureNode(depthTex, uvNode()).r.mul(displacementScale);
      rowMat.needsUpdate = true;
    });
  }

  // --- parallax primitive (render mode requires subtle parallax) ---
  let parallax = null;
  if (ctx.primitives && typeof ctx.primitives['parallax-scroll'] === 'function') {
    parallax = ctx.primitives['parallax-scroll'](root, {
      amplitude: 0.035,
      speed: 0.45,
      axis: 'xy',
      trigger: 'time',
    });
  }

  // --- interaction timelines ---
  const hoverTl = gsap.timeline({ paused: true });
  hoverTl.to(content.position, { y: 0.15, duration: 0.45, ease: 'power2.out' });

  const pressTl = gsap.timeline({ paused: true });
  pressTl.to(content.scale, { x: 0.97, y: 0.97, z: 0.97, duration: 0.12, ease: 'back.out(1.2)' });

  // --- event handlers ---
  root.userData.handlers = {
    hover: () => {
      hoverTl.play();
    },
    hoverOut: () => {
      hoverTl.reverse();
    },
    pointerdown: () => {
      pressTl.play();
    },
    pointerup: () => {
      pressTl.reverse();
    },
    click: () => {
      ctx.emit('hub-features.select', { nodeId: config.id });
      ctx.emit('navigate', { to: 'hub-features' });
    },
  };

  // --- cleanup ---
  root.userData.cleanup = () => {
    if (parallax && typeof parallax.cleanup === 'function') parallax.cleanup();
    hoverTl.kill();
    pressTl.kill();

    rim.dispose();
    if (rowMat.map && rowMat.map.dispose) rowMat.map.dispose();
    if (rowMat.displacementNode) rowMat.displacementNode = null;
    rowMat.dispose();
    stageMat.dispose();
    divMat.dispose();

    rowGeo.dispose();
    stageGeo.dispose();
    divGeo.dispose();
  };

  return root;
}
